         starter_code='from collections import deque\n\ndef word_ladder_length(begin_word, end_word, word_list):\n    # Think of every word as a NODE, with an edge between two words that\n    # differ by exactly one letter. The shortest transformation sequence\n    # is then just a shortest PATH in this implicit graph -- exactly what\n    # BFS is for.\n    pass\n',
