         function_signature='def kth_smallest_bst(values, k):',
         starter_code="class TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values or values[0] is None:\n        return None\n    root = TreeNode(values[0])\n    queue = [root]\n    i = 1\n    while queue and i < len(values):\n        node = queue.pop(0)\n        if i < len(values):\n            lv = values[i]; i += 1\n            if lv is not None:\n                node.left = TreeNode(lv)\n                queue.append(node.left)\n        if i < len(values):\n            rv = values[i]; i += 1\n            if rv is not None:\n                node.right = TreeNode(rv)\n                queue.append(node.right)\n    return root\n\ndef kth_smallest_bst(values, k):\n    root = build_tree(values)\n    # A BST's IN-ORDER traversal (left, node, right) visits every value\n    # in sorted order -- so the kth value visited during an in-order walk\n    # IS the kth smallest, with no separate sorting step needed.\n    pass\n",
