         starter_code="from collections import Counter\nimport heapq\n\ndef least_interval(tasks, n):\n    # Greedy idea: at every time step, run whichever REMAINING task type\n    # currently has the most instances left (a max-heap gives you that in\n    # O(log k)). After running a task, it needs to 'cool down' for n\n    # steps before it's eligible again -- track that with a small queue\n    # of (time-it-becomes-available-again, remaining-count) pairs.\n    pass\n",
