         reference_solution='from collections import Counter\nimport heapq\n\ndef least_interval(tasks, n):\n    counts = list(Counter(tasks).values())\n    heap = [-c for c in counts]\n    heapq.heapify(heap)\n    time = 0\n    q = []\n    while heap or q:\n        time += 1\n        if heap:\n            c = -heapq.heappop(heap) - 1\n            if c > 0:\n                q.append((time + n, c))\n        if q and q[0][0] == time:\n            heapq.heappush(heap, -q.pop(0)[1])\n        if not heap and q:\n            time = q[0][0] - 1\n    return time\n',
